function renderToday(){const day=focusDay,tasks=tasksFor(day),done=publishedCount(),complete=tasks.filter(t=>state.tasks[t.id]).length,cur=profileLatest();const upcoming=P.posts.find(p=>p.date===day)||P.posts.find(p=>ps(p.id).status!=='published'&&p.date>=day)||P.posts.find(p=>ps(p.id).status!=='published');const due=deadlines().filter(d=>!d.done&&Date.parse(d.at)<=Date.now()),nextReview=fixedTasks.find(t=>t.kind==='review'&&t.day>=today());return `<div class="pagehead"><div><p class="eyebrow">${esc(longDate(day))} · ${day>=P.start&&day<=P.end?'ДЕН '+challengeDay(day):'ТВОЯТ ПЛАН'}</p><h1>Твоят ден<span class="accent">.</span></h1></div>${btn(icon('settings'),'settings','iconbtn','aria-label="Настройки и архив"')}</div>${dayRail(day)}<div class="studio-layout"><div class="stack">${upcoming?`<article class="card studio-feature"><div class="feature-art" aria-hidden="true"></div><div class="feature-content"><div class="posttop"><span class="tag">${upcoming.type==='reel'?'REEL':'КАРУСЕЛ'} · ${shortDate(upcoming.date)}</span><span class="small">${statusLabel(upcoming.id)}</span></div><p class="eyebrow" style="margin-top:25px">${P.pillars[upcoming.pillar].name} ${upcoming.duration?' / '+upcoming.duration+' СЕК':''}</p><h2>${esc(upcoming.title)}</h2><p class="hookquote">„${esc(upcoming.hook)}“</p><div class="actions">${btn(icon('play',true)+' Отвори сценария','open-post','primary',`data-id="${upcoming.id}"`)}</div></div></article><div class="workflow"><button data-action="open-post" data-id="${upcoming.id}"><span>01</span><b>Подготви</b>${icon('copy',true)}</button><button data-action="focus-start" data-id="${upcoming.id}"><span>02</span><b>Сними</b>${icon('play',true)}</button><button data-action="open-metrics" data-id="${upcoming.id}"><span>03</span><b>Отчети</b>${icon('results',true)}</button></div>`:'<article class="card light"><h2>Всички публикации са отметнати.</h2><p>Продължаваме с отчетите и следващите решения.</p></article>'}<section class="card tasks-card"><div class="sectiontitle"><div><p class="eyebrow">${complete} ОТ ${tasks.length} ГОТОВИ</p><h2>Малките стъпки</h2></div>${btn(hideCompleted?'Всички':'Оставащи','task-view','small',`aria-pressed="${hideCompleted}"`)}</div><div class="progress"><span style="width:${tasks.length?complete/tasks.length*100:0}%"></span></div>${tasks.filter(t=>!hideCompleted||!state.tasks[t.id]).map(taskHTML).join('')||'<p class="empty">Няма оставащи задачи за този ден.</p>'}</section></div><aside class="stack"><div class="studio-stats"><div class="card progress-card"><svg viewBox="0 0 100 100" role="img" aria-label="${done} от 16 публикации"><circle cx="50" cy="50" r="42" fill="none" stroke="currentColor" stroke-width="7" opacity=".13"/><circle cx="50" cy="50" r="42" fill="none" stroke="#ffb25a" stroke-width="7" stroke-linecap="round" pathLength="100" stroke-dasharray="${done/16*100} 100" transform="rotate(-90 50 50)"/><text x="50" y="54" text-anchor="middle" fill="currentColor" font-size="29" font-weight="700">${done}</text><text x="50" y="70" text-anchor="middle" fill="currentColor" font-size="12">от 16</text></svg><b>Публикации</b><span class="small muted">До 30 септември</span></div><button class="card follower-card" data-action="settings"><span class="eyebrow">ПРОФИЛЪТ</span><strong>${cur?fmt(cur.followers):state.profile.baselineConfirmed?fmt(state.profile.baseline):'—'}</strong><b>Последователи</b><span class="small muted">${cur||state.profile.baselineConfirmed?'Цел: '+fmt(P.goal):'Въведи началния брой'} ${icon('next',true)}</span></button></div>${due.length?`<section class="card warm"><div class="sectiontitle"><h2>Време за числа</h2><span class="tag">${due.length}</span></div>${due.slice(0,3).map(deadlineHTML).join('')}${btn('Всички отчети','navigate','small','data-route="results"')}</section>`:''}${nextReview?`<section class="card review-card"><span class="eyebrow">СЛЕДВАЩ АНАЛИЗ</span><div class="review-date">${Number(nextReview.day.slice(8))}<span>${nextReview.day.slice(5,7)==='10'?'ОКТ':'СЕП'}</span></div><h3>${esc(nextReview.title)}</h3><p class="muted small">Числата → един извод → следваща стъпка.</p>${btn('Към резултатите '+icon('arrow',true),'navigate','','data-route="results"')}</section>`:''}</aside></div><section class="upcoming-section"><div class="sectiontitle"><h2>На хоризонта</h2>${btn('Целият план','navigate','small','data-route="calendar"')}</div><div class="post-shelf">${P.posts.filter(p=>p.date>day).slice(0,4).map(postCard).join('')||'<p class="muted">Остава да съберем последните отчети.</p>'}</div></section>`}
function focusFrames(p){if(ps(p.id).scriptOverride?.trim())return [['Финална редакция',p.prep,script(p),'Използвай редактирания сценарий; първоначалните монтажни указания са в картата.']];return p.type==='reel'?p.beats:p.slides.map((x,i)=>['Слайд '+(i+1),x[1],x[0],'Текстът на слайда'])}
function renderFocus(){const p=getPost(currentPost),steps=focusFrames(p),b=steps[focusStep];$('#focus-dialog').innerHTML=`<div class="focus-head"><span class="eyebrow">${p.type==='reel'?'СНИМАНЕ':'СЛАЙДОВЕ'} · ${focusStep+1} / ${steps.length}</span>${btn(icon('close'),'focus-close','iconbtn','aria-label="Затвори режима за снимане"')}</div><div class="focus-progress">${steps.map((_,i)=>`<span class="${i<=focusStep?'done':''}"></span>`).join('')}</div><div class="focus-body" aria-live="polite"><span class="focus-time">${esc(b[0])}${p.type==='reel'&&steps.length>1?' сек':''}</span><h2 id="focus-title">${p.type==='reel'?'Казваш':'На слайда'}</h2><p class="focus-spoken">${esc(fill(b[2],p))}</p><div class="focus-instruction"><span class="eyebrow">КАДЪР</span><p>${esc(b[1])}</p></div><div class="focus-instruction"><span class="eyebrow">ТЕКСТ НА ЕКРАНА</span><p>${esc(fill(b[3],p))}</p></div></div><div class="focus-controls">${btn(icon('back')+' Назад','focus-prev','',focusStep===0?'disabled':'')}${focusStep===steps.length-1?btn(icon('check',true)+' Заснето','focus-done','primary'):btn('Следващ '+icon('next'),'focus-next','primary')}</div>`}
function renderCalendar(){const first=month+'-01',dow=(new Date(first+'T12:00Z').getUTCDay()+6)%7,start=plusDays(first,-dow);const last=new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate();const cells=calendarMode==='week'?7:Math.ceil((dow+last)/7)*7;const gridStart=calendarMode==='week'?plusDays(selected,-((new Date(selected+'T12:00Z').getUTCDay()+6)%7)):start;const dl=deadlines();let days='';for(let i=0;i<cells;i++){const d=plusDays(gridStart,i),posts=P.posts.filter(p=>p.date===d);const ts=tasksFor(d).filter(t=>t.kind!=='story');const ds=dl.filter(x=>x.day===d&&!x.done);days+=`<button type="button" class="day ${d===selected?'selected':''} ${d===today()?'today':''} ${d.slice(0,7)!==month?'out':''}" data-action="day" data-day="${d}" aria-label="${esc(longDate(d))}: ${posts.length} публикации, ${ts.length} задачи, ${ds.length} отчета" aria-pressed="${d===selected}"><span>${Number(d.slice(8))}</span><span class="daymarks">${posts.map(p=>`<i class="daymark" style="background:${pColor(p)}"></i>`).join('')}${ts.length?'<i class="daymark taskmark"></i>':''}${ds.length?'<i class="daymark metricmark"></i>':''}</span></button>`}
const selectedPosts=P.posts.filter(p=>p.date===selected),tasks=tasksFor(selected),metrics=dl.filter(d=>d.day===selected);return `<div class="pagehead"><div><p class="eyebrow">08–30 СЕПТЕМВРИ 2026</p><h1>Календарът ти.</h1><p class="muted">Публикации, снимане и анализ — по дни.</p></div>${btn('Днес','calendar-today','small')}</div><div class="twocol calcolumns"><div class="stack calsticky"><section class="card calendarcard"><div class="calendar-switch">${[['week','Седмица'],['month','Месец']].map(([id,label])=>btn(label,'calendar-mode',calendarMode===id?'active':'',`data-mode="${id}" aria-pressed="${calendarMode===id}"`)).join('')}</div>${calendarMode==='week'?`<div class="week-pager">${btn(icon('back'),'week-prev','iconbtn','aria-label="Предишна седмица"')}<span>${shortDate(gridStart)} – ${shortDate(plusDays(gridStart,6))}</span>${btn(icon('next'),'week-next','iconbtn','aria-label="Следваща седмица"')}</div>`:''}<div class="calendarhead">${btn(icon('back'),'month-prev','iconbtn','aria-label="Предишен месец" '+(month==='2026-09'?'disabled':''))}<h2>${month==='2026-09'?'Септември':'Октомври'} 2026</h2>${btn(icon('next'),'month-next','iconbtn','aria-label="Следващ месец" '+(month==='2026-10'?'disabled':''))}</div><div class="calendargrid">${['П','В','С','Ч','П','С','Н'].map(x=>`<span class="weekday">${x}</span>`).join('')}${days}</div><div class="callegend">${Object.values(P.pillars).map(p=>`<span><i class="daymark" style="background:${p.color}"></i>${p.name}</span>`).join('')}<span><i class="daymark taskmark"></i>Задача</span><span><i class="daymark metricmark"></i>Отчет</span></div></section><div class="notice">Отчетите на <strong>48 часа и 7 дни</strong> се появяват, когато отбележиш реалния час на публикуване. Последните септемврийски отчети са през октомври.</div></div><div class="stack"><div class="sectiontitle"><h2>${esc(longDate(selected))}</h2></div>${selectedPosts.map(postCard).join('')}${!selectedPosts.length?'<p class="muted">Няма планирана публикация във фийда.</p>':''}${metrics.length?`<div class="card warm"><h3>Отчети за деня</h3>${metrics.map(deadlineHTML).join('')}</div>`:''}${tasks.length?`<div class="card">${tasks.map(taskHTML).join('')}</div>`:''}</div></div><section><div class="sectiontitle"><h2>Всички публикации</h2><span class="small muted">13 Reels · 3 карусела</span></div><div class="filters">${[['all','Всички'],...Object.entries(P.pillars).map(([id,p])=>[id,p.name])].map(([id,label])=>`<button class="chip ${filter===id?'active':''}" data-action="filter" data-filter="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div><div class="twocol">${P.posts.filter(p=>filter==='all'||p.pillar===filter).map(postCard).join('')}</div></section>`}
function eligibleRows(key){return P.posts.filter(p=>p.type==='reel').flatMap(p=>{const s=ps(p.id),snap=s.snapshots?.[key];return s.status==='published'&&snap&&comparable(s,snap,key)?[{post:p,snap,r:rates(snap.values,s.duration??null)}]:[]})}
function summaryValues(rows,access){const vals=rows.map(access).filter(finite);return {value:median(vals),count:vals.length}}
function summaryCell(rows,access,suffix='',digits=1){const s=summaryValues(rows,access);return `${fmt(s.value,digits)}${s.value!==null?suffix:''}<br><span class="small muted">n=${s.count}</span>`}
function renderResults(){const eligible=eligibleRows(metricWindow),allSnaps=P.posts.filter(p=>ps(p.id).snapshots?.[metricWindow]);const late=allSnaps.filter(p=>!comparable(ps(p.id),ps(p.id).snapshots[metricWindow],metricWindow));const current=profileLatest();const delta=current&&state.profile.baselineConfirmed?current.followers-state.profile.baseline:null;const hit=eligible.filter(x=>x.snap.values.views!==null&&x.snap.values.views>=P.viewGoal).length;const due=deadlines().filter(d=>!d.done&&Date.parse(d.at)<=Date.now());const expected=deadlines().filter(d=>!d.done&&Date.parse(d.at)>Date.now()).slice(0,3);const dates=fixedTasks.filter(x=>x.kind==='review').map(x=>x.day);const reviewDate=dates.filter(x=>x<=today()).at(-1)||dates[0];
return `<div class="pagehead"><div><p class="eyebrow">ЧИСЛА → ЕДНО ЯСНО РЕШЕНИЕ</p><h1>Как върви процесът?</h1><p class="muted">Отчиташ в Instagram. Тук попълваш числата.</p></div>${btn(icon('settings'),'settings','iconbtn','aria-label="Настройки и архив"')}</div>
<div class="card light"><div class="posttop"><h2>Отчет за нашия анализ</h2><span class="tag">${publishedCount()} / 16 публикувани</span></div><p class="muted" style="margin-top:10px">Натисни „Сподели за анализ“ и прикачи файла в чата. В него са планът, резултатите, възрастта на отчетите и бележките ти.</p><div class="actions" style="margin-top:18px">${btn(icon('upload',true)+' Сподели за анализ','share-report','primary')}${btn(icon('download',true)+' Изтегли отчет','download-report')}${btn('Архив .json','backup')}</div><p class="small muted" style="margin-top:12px">Отчетът е за четене и анализ. Архивът пази данните за възстановяване или друг телефон.</p></div>
<div class="sectiontitle"><h2>Сравняваме еднаква възраст</h2></div><div class="filters">${[['48h','48 часа'],['7d','7 дни']].map(([key,label])=>`<button class="chip ${metricWindow===key?'active':''}" data-action="metric-window" data-window="${key}" aria-pressed="${metricWindow===key}">${label}</button>`).join('')}</div>
<div class="rating"><div><span class="small muted">Медиана гледания</span><b>${fmt(median(eligible.map(x=>x.snap.values.views)))}</b><span class="small muted">${eligible.filter(x=>finite(x.snap.values.views)).length} отчета с гледания</span></div><div><span class="small muted">Reels с 10 000+</span><b>${hit} / 13</b><span class="small muted">Цел за всяко видео</span></div><div><span class="small muted">Ръст на профила</span><b>${delta===null?'—':(delta>0?'+':'')+fmt(delta)}</b><span class="small muted">${current?stampLabel(current.at):'Няма текущ отчет'}</span></div></div>
<p class="small muted" style="margin:13px 0 20px">Сравним прозорец: ${metricWindow==='48h'?'48–72 часа':'168–192 часа'} след реалното публикуване. Това е наше правило за анализ. Непопълнено = няма данни.${late.length?' '+late.length+' отчета са извън прозореца и остават само в подробностите и експорта.':''}</p>
<div class="twocol"><div class="stack"><section class="card"><h2>${due.length?'За попълване сега':'Следващи отчети'}</h2>${due.length?due.map(deadlineHTML).join(''):expected.length?expected.map(deadlineHTML).join(''):'<p class="empty">След като отбележиш публикация, тук ще се появят сроковете за нейните числа.</p>'}</section><section class="card"><h2>Групи по формат</h2><p class="small muted" style="margin-top:8px">Само Reels от избрания прозорец. n е броят налични стойности за съответния показател.</p><div class="tablewrap"><table><thead><tr><th>Формат</th><th>Гледания</th><th>Последвания / 1000</th><th>Споделяния %</th></tr></thead><tbody>${['Демонстрация','Минивлог','Личен разказ'].map(f=>{const group=eligible.filter(x=>x.post.format===f);return `<tr><td>${f}<br><span class="small muted">${group.length<3?'Недостатъчна извадка':'Ранен ориентир'}</span></td><td>${summaryCell(group,x=>x.snap.values.views,'',0)}</td><td>${summaryCell(group,x=>x.r.followsPer1000)}</td><td>${summaryCell(group,x=>x.r.shareRate,'%')}</td></tr>`}).join('')}</tbody></table></div></section></div>
<div class="stack"><section class="card warm"><h2>Решението след прегледа</h2><p class="small muted" style="margin:8px 0 16px">Един извод и една промяна за следващ нов материал.</p><form id="review-form"><div class="formgrid"><label class="field wide">Дата на прегледа<select name="reviewDate" id="review-date">${dates.map(d=>`<option value="${d}" ${d===reviewDate?'selected':''}>${shortDate(d)}${d==='2026-10-07'?' · пълен отчет':''}</option>`).join('')}</select></label><label class="field wide">Извод • какво запазвам • какво променям<textarea name="reviewNote" id="review-note" placeholder="Например: първият кадър е неясен. При следващата демонстрация показвам готовия резултат веднага.">${esc(state.reviews[reviewDate]||'')}</textarea></label></div><div class="actions"><button class="btn primary" type="submit">Запази решението</button></div></form></section><section class="card"><h2>Как взимаме решение</h2><ol class="list small"><li>Първо изпълнимостта: успяваш ли да снимаш без претоварване?</li><li>При ранно отпадане: по-ясен първи кадър и по-точно обещание.</li><li>При спад по средата: покажи действието по-рано и махни повторението.</li><li>При гледания и малко последвания: по-ясна връзка с 180-те дни и конкретно продължение.</li><li>Повтаряме принцип само след повторен сигнал. При по-малко от 3 сравними материала в групата записваме хипотеза.</li></ol><p class="small muted" style="margin-top:13px">И при 3 материала резултатът е предварителен. Тема, час и аудитория се различават; това не е контролиран A/B тест.</p></section></div></div>
<section class="card" style="margin-top:20px"><h2>По публикации</h2><p class="small muted" style="margin-top:8px">Каруселите имат собствени редове и не участват в медианите за Reels.</p><div class="tablewrap"><table class="post-results"><thead><tr><th>Публикация</th><th>Гледания</th><th>Обхват</th><th>Средно, сек</th><th>Последвания / 1000</th><th>Споделяния %</th><th>Запазвания %</th><th>Отчет</th></tr></thead><tbody>${P.posts.map(p=>{const s=ps(p.id),snap=s.snapshots?.[metricWindow],v=snap?.values||{},r=rates(v,s.duration??null);return `<tr><td><button class="plainlink" data-action="open-metrics" data-id="${p.id}" data-window="${metricWindow}">${shortDate(p.date)} · ${esc(p.title)}</button><br><span class="small muted">${p.type==='carousel'?'Карусел':p.format}</span></td><td data-label="Гледания">${fmt(v.views)}</td><td data-label="Обхват">${fmt(v.reach)}</td><td data-label="Средно, сек">${p.type==='reel'?fmt(v.avgWatch,1):'—'}</td><td data-label="Последвания / 1000">${fmt(r.followsPer1000,1)}</td><td data-label="Споделяния %">${fmt(r.shareRate,2)}</td><td data-label="Запазвания %">${fmt(r.saveRate,2)}</td><td data-label="Отчет">${snap?(comparable(s,snap,metricWindow)?'В прозореца':'Извън прозореца')+'<br><span class="small muted">'+fmt(snapshotAge(s,snap),1)+' ч.</span>':'Няма данни'}</td></tr>`}).join('')}</tbody></table></div></section>`}
function renderStrategy(){const trendDates=['2026-09-14','2026-09-21','2026-09-28'];const chosen=trendDates.filter(d=>d<=today()).at(-1)||trendDates[0];return `<div class="pagehead"><div><p class="eyebrow">РЕДАКЦИЯ 08.09.2026</p><h1>Посоката остава твоя.</h1><p class="muted">Работа. Семейство. Тяло. Нови умения.</p></div></div>
<div class="card light"><p class="eyebrow">ОБЕЩАНИЕТО НА ПРОФИЛА</p><h2 style="font-size:1.6rem;margin:13px 0">От „утре започвам“<br>към реални действия.</h2><p>Показвам как работещ съпруг и баща изгражда по-силно тяло, по-подредено хранене, нови умения и повече присъствие вкъщи — в 180 истински дни.</p><p class="small muted">Говорим на български на заети хора със сходни отговорности. Възраст 25–40 е работна хипотеза; нямаме измерена демография от Insights.</p></div>
<div class="twocol" style="margin-top:20px"><div class="stack"><section class="card"><h2>Как надградихме плана</h2><p class="small muted" style="margin-top:10px">Прочетени: последният „Bobyziad_Instagram_Plan.pdf“ (75 стр., обновен 08.09) и „180_dni_pozicionirane_i_auditoria.docx“. Запазени са всички 16 септемврийски публикации от PDF; октомврийските не са добавяни към новия календар.</p><details><summary>Виж редакционния одит</summary>${P.audit.map(a=>`<div class="auditrow"><p class="eyebrow">${esc(a[0])}</p><h3>${esc(a[1])}</h3><p class="small muted">${esc(a[2])}</p></div>`).join('')}</details><details><summary>Какво знаем за досегашните резултати</summary><p class="small">В предишния PDF са описани отделни видими гледания: 6399 за сутрин/легло, 6214 за „Как мъжете губим 30 минути“, 5813 за семеен епизод и 4410 за храна. Различната възраст и липсващите Insights не позволяват надеждна класация.</p><p class="small">Тук не е направен нов преглед на всички публикации или на личните Insights. Новият блок събира сравними данни.</p></details></section>
<section class="card"><h2>Снимаш по една ясна карта</h2><details open><summary>Формат, звук и текст</summary><ul class="list small"><li>Reel: 1080×1920, вертикално 9:16. Практичен експорт: 30 кадъра/сек, H.264. Карусел: 1080×1350.</li><li>Първият кадър показва резултат или конкретен въпрос. Хукът се казва първи. Без поздрав и интро.</li><li>Ориентир 26–38 сек. Прочети текста на глас; адаптирай монтажа към естествения говор.</li><li>Субтитри на български за всяка говорна част, до два кратки реда. В картите „само субтитри“ означава без допълнително заглавие.</li><li>Практична начална зона при 1080×1920: остави около 120 px отстрани, 250 px отгоре и 420 px отдолу за важния текст. Провери реалния preview на Instagram — това е монтажен ориентир, не официална универсална безопасна зона.</li><li>Голямото заглавие в началото може да замести субтитъра само ако изписва целия говор. Иначе добави краткия субтитър отделно, без да закрива резултата.</li><li>Когато няма говор, остави чист кадър и естествения звук. При записи с числа не поставяй субтитри върху тях.</li><li>Сменяй кадъра при ново действие или мисъл. Собствен глас; музика само ако не пречи. Проверени субтитри и експорт без чужд воден знак.</li></ul></details><details><summary>Корицата и описанието</summary><p class="small">Собствен кадър, четимо кратко заглавие от картата, бял удебелен шрифт и един светъл жълт акцент. Важният текст е централно; провери изрязването в профила.</p><p class="small">Описанието е готово във всяка карта. Първият ред назовава темата; следват кратък контекст и един призив. Двата-три конкретни хаштага са редакционен избор, а не обещание за рийч.</p></details><details><summary>Когато седмицата е тежка</summary><p class="small">Използвай краткия резервен вариант в картата: лице, едно доказателство и един финал. Ако и това не се побира, приоритет са сряда, петък и понеделник. Не качваш двойно за наваксване; отбелязваш причината.</p><p class="small">Неделя: 30–40 минути. Понеделник: 75–90 минути. Останалите кадри са от реалната тренировка или готвене. Детският сън е възможен прозорец, не гарантиран график.</p></details></section>
<section class="card"><h2>Профил, който има продължение</h2><p class="small muted" style="margin:9px 0 14px">Поле за име: Боби | 180 дни промяна</p><div class="copytext">Баща и съпруг с работа 10–19.\n180 дни: тяло, нови умения, време за семейството.\nПоказвам процеса и напредъка.</div><div class="actions" style="margin-top:14px">${btn(icon('copy',true)+' Копирай био','copy-bio','small')}</div><p class="small" style="margin-top:15px">Закрепи съществуващото ясно начално видео. След публикуването добави практическата карта 01 и карта 05 за ученето. Акценти: Начало, Форма, Храна, Учене, Живот.</p><p class="small muted">Всеки Reel се разбира самостоятелно. Продълженията от 11 → 18.09 и 14 → 21.09 дават причина човек да се върне. Семейството е контекст; твоите действия са достатъчни за кадрите.</p></section></div>
<div class="stack"><section class="card warm"><div class="posttop"><h2>Трендовете през нашия филтър</h2><span class="tag">Проверка: 08.09</span></div><p class="small muted" style="margin:12px 0 18px">Подбраните мотиви са международни наблюдения от началото на септември. Българска ефективност и наличност на конкретно аудио не са потвърдени. Хуковете в картите са написани за теб; не са чужди доказано вирусни реплики.</p>${P.trends.map(t=>`<div class="trend"><span class="eyebrow">${esc(t.label)}</span><h3>${esc(t.name)}</h3><p class="small">${esc(t.detail)}</p><a class="small" href="${P.sources.find(s=>s.id===t.source).url}" target="_blank" rel="noopener noreferrer">Източник: ${P.sources.find(s=>s.id===t.source).name}</a></div>`).join('')}</section>
<section class="card"><h2>Следваща проверка на тенденциите</h2><p class="small muted" style="margin:9px 0 16px">14, 21 и 28 септември. Готовият план остава в сила, ако няма подходящ нов пример. Приложението не следи Instagram във фонов режим.</p><form id="trend-form"><div class="formgrid"><label class="field wide">Планирана проверка<select name="trendDate" id="trend-date">${trendDates.map(d=>`<option value="${d}" ${d===chosen?'selected':''}>${shortDate(d)}</option>`).join('')}</select></label><label class="field wide">Линк • какво виждам • какво взимам<textarea name="trendNote" id="trend-note" placeholder="Линк към реален пример, дата на публикацията, хук/монтаж и една приложима идея.">${esc(state.trendChecks[chosen]?.notes||'')}</textarea></label></div><div class="actions"><button class="btn primary" type="submit">Запази проверката</button></div></form><p class="small muted" style="margin-top:14px">Не заключавай „тренд“ само от голям брой гледания. Потърси повторение в няколко скорошни примера; публичните гледания не показват задържане и последвания.</p></section>
<section class="card"><h2>Какво означават целите</h2><p style="margin-top:12px">500 последователи до 30.09 и поне 10 000 гледания на всяко Reel са амбициозни цели. От последно споделените 205 до 500 са +295 нетно; това не е прогнозираният резултат.</p><p class="small muted">Проследяваме броя Reels над 10 000 и медианата, а не само най-силното видео. За растежа на профила използваме общия брой последователи; отделните последвания от Reels не включват всички други източници и отписвания.</p><p class="small">Наша изпълнима цел: 16 готови публикации, реални доказателства, попълнени налични показатели и един извод на преглед. Няма гаранция за вирусно разпространение.</p></section></div></div>
<section class="card" style="margin-top:20px"><h2>Източници и граници на проучването</h2><p class="small muted" style="margin-top:8px">Прочетени на 08.09.2026. По-късните проверки се записват отделно; тези страници може да бъдат обновявани от издателите.</p>${P.sources.map(s=>`<div class="source"><div class="posttop"><a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(s.name)}</a><span class="small muted">${s.date}</span></div><p class="small">${esc(s.note)}</p><span class="eyebrow">${esc(s.type)}</span></div>`).join('')}</section>`}

startApp();
